   157→/* Custom animations for fashion app */
   158→@keyframes typing {
   159→  0%,
   160→  60%,
   161→  100% {
   162→    transform: translateY(0);
   163→  }
   164→  30% {
   165→    transform: translateY(-10px);
   166→  }
   167→}
   168→
   169→@keyframes fadeInUp {
   170→  from {
   171→    opacity: 0;
   172→    transform: translateY(20px);
   173→  }
   174→  to {
   175→    opacity: 1;
   176→    transform: translateY(0);
   177→  }
   178→}
   179→
