   200→    rgba(255, 255, 255, 0) 0%,
   201→    rgba(255, 255, 255, 0.4) 50%,
   202→    rgba(255, 255, 255, 0) 100%
   203→  );
   204→  background-size: 1000px 100%;
   205→  animation: shimmer 2s infinite;
   206→}
   207→
   208→/* Z-index hierarchy for proper overlay stacking */
   209→.z-header {
   210→  z-index: 40;
   211→}
   212→
   213→.z-sidebar {
   214→  z-index: 30;
   215→}
   216→
   217→.z-dropdown {
   218→  z-index: 50;
   219→}
   220→
   221→.z-modal-overlay {
   222→  z-index: 60;
   223→}
   224→
   225→.z-modal-content {
   226→  z-index: 61;
   227→}
   228→
   229→.z-toast {
   230→  z-index: 100;
   231→}
   232→
   233→/* Prevent body scroll when modal is open */
   234→.modal-open {
   235→  overflow: hidden;
   236→  padding-right: var(--scrollbar-width, 0);
   237→}
   238→
   239→/* Consistent backdrop styling */
   240→.overlay-backdrop {
   241→  background-color: rgba(0, 0, 0, 0.75);
   242→  backdrop-filter: blur(4px);
   243→}
   244→
   245→/* Fix for mobile viewport issues */
   246→@supports (height: 100dvh) {
   247→  .min-h-screen {
   248→    min-height: 100dvh;
   249→  }
   250→}
   251→
   252→/* Mobile touch target sizing - minimum 44x44px */
   253→@media (max-width: 768px) {
   254→  .touch-target,
   255→  button:not(.no-touch-target),
   256→  a:not(.no-touch-target),
   257→  [role="button"]:not(.no-touch-target) {
   258→    min-width: 44px;
   259→    min-height: 44px;
   260→  }
   261→
   262→  /* Gallery dots - proper touch size */
   263→  .image-indicator {
   264→    min-width: 44px;
   265→    min-height: 44px;
   266→    display: inline-flex;
   267→    align-items: center;
   268→    justify-content: center;
   269→  }
   270→
   271→  .image-indicator > * {
   272→    width: 12px;
   273→    height: 12px;
   274→  }
   275→
   276→  /* Size and color selectors */
   277→  .size-selector,
   278→  .color-selector {
   279→    min-width: 44px;
   280→    min-height: 44px;
   281→    padding: 8px 12px;
   282→  }
   283→}
   284→
   285→/* Onboarding Styles */
   286→@keyframes slideInRight {
   287→  from {
   288→    opacity: 0;
   289→    transform: translateX(20px);
   290→  }
   291→  to {
   292→    opacity: 1;
   293→    transform: translateX(0);
   294→  }
   295→}
   296→
   297→@keyframes slideInLeft {
   298→  from {
   299→    opacity: 0;
   300→    transform: translateX(-20px);
   301→  }
   302→  to {
   303→    opacity: 1;
   304→    transform: translateX(0);
   305→  }
   306→}
   307→
   308→.onboarding-container {
   309→  min-height: 100vh;
   310→  background-color: var(--onboarding-bg);
   311→}
   312→
   313→.onboarding-screen-enter {
   314→  animation: slideInRight 0.3s ease-out;
   315→}
   316→
   317→.onboarding-screen-exit {
   318→  animation: slideInLeft 0.3s ease-out;
   319→}
   320→
   321→/* Onboarding circular arrow button */
   322→.onboarding-next-button {
   323→  width: 56px;
   324→  height: 56px;
   325→  border-radius: 50%;
   326→  background-color: var(--onboarding-primary);
   327→  color: white;
   328→  display: flex;
   329→  align-items: center;
   330→  justify-content: center;
   331→  border: none;
   332→  cursor: pointer;
   333→  transition: all 0.3s ease;
   334→}
   335→
   336→.onboarding-next-button:hover:not(:disabled) {
   337→  background-color: var(--onboarding-primary-hover);
   338→  transform: scale(1.05);
   339→}
   340→
   341→.onboarding-next-button:disabled {
   342→  background-color: #D1D5DB;
   343→  cursor: not-allowed;
   344→}
   345→
   346→/* Style carousel custom scrollbar */
   347→.embla {
   348→  overflow: hidden;
   349→}
   350→
   351→.embla__container {
   352→  display: flex;
   353→  gap: 1rem;
   354→}
   355→
   356→.embla__slide {
   357→  flex: 0 0 280px;
   358→  min-width: 0;
   359→}
   360→
   361→/* Selection Carousel Card Animations */
   362→.selection-carousel-card {
   363→  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
   364→}
   365→
   366→.selection-carousel-card:hover {
   367→  transform: translateY(-4px);
   368→  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.1);
   369→}
   370→
   371→.selection-carousel-card:active {
   372→  transform: translateY(-2px);
   373→}
   374→
   375→/* Selection thumbnail animation */
   376→.selection-thumbnail-enter {
   377→  animation: thumbnailEnter 0.3s ease-out;
   378→}
   379→
   380→@keyframes thumbnailEnter {
   381→  from {
   382→    opacity: 0;
   383→    transform: scale(0.8);
   384→  }
   385→  to {
   386→    opacity: 1;
   387→    transform: scale(1);
   388→  }
   389→}
   390→
   391→/* Carousel card selection state */
   392→.carousel-card-selected {
   393→  border-color: var(--onboarding-card-border-selected);
   394→  box-shadow: 0 4px 15px -3px rgba(212, 181, 181, 0.4);
   395→}
   396→
   397→/* Smooth border transition for selection */
   398→.carousel-card-border {
   399→  transition: border-color 0.3s ease, box-shadow 0.3s ease;
   400→}
   401→
   402→/* Hide scrollbar for selected items row */
   403→.hide-scrollbar {
   404→  -ms-overflow-style: none;
   405→  scrollbar-width: none;
   406→}
   407→
   408→.hide-scrollbar::-webkit-scrollbar {
   409→  display: none;
   410→}
